(async () => {
  const b64 = '';
  const nonce = wpApiSettings.nonce;
  const bs = atob(b64);
  const ab = new ArrayBuffer(bs.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < bs.length; i++) ia[i] = bs.charCodeAt(i);
  const file = new File([ab], 'accessing-thrive-apprentice_step3.png', { type: 'image/png' });
  const fd = new FormData();
  fd.append('file', file);
  const resp = await fetch('/wp-json/wp/v2/media', { method: 'POST', headers: { 'X-WP-Nonce': nonce }, body: fd });
  if (!resp.ok) return 'ERR:' + resp.status + ':' + (await resp.text()).substring(0,100);
  const m = await resp.json();
  await fetch('/wp-json/wp/v2/media/' + m.id, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': nonce }, body: JSON.stringify({ alt_text: 'Accessing Thrive Apprentice - Thrive Apprentice in Thrive Apprentice' }) });
  if (!window.__ur) window.__ur = {};
  window.__ur['accessing-thrive-apprentice_step3.png'] = { id: m.id, url: m.source_url, alt: 'Accessing Thrive Apprentice - Thrive Apprentice in Thrive Apprentice' };
  return 'OK:' + m.id + ':' + m.source_url;
})();
